// Shared definition of the 7 representative export fixtures, used by both the
// regeneration script (scripts/generate-export-fixtures.mjs) and the drift test
// (tests/unit/export-fixtures.test.js) so the two can never silently disagree about
// what a fixture's input configuration was.

import { generateIframeContent } from '../../js/preview.js';
import { COMPONENT_REGISTRY, getComponentById, getDefaultConfig } from '../../js/component-registry.js';
import { BUILT_IN_THEMES, DEFAULT_THEME_ID, applyThemeToConfig } from '../../js/themes.js';
import { toRgba } from '../../js/utilities.js';

const theme = BUILT_IN_THEMES.find(entry => entry.id === DEFAULT_THEME_ID);
const componentRegistry = Object.fromEntries(COMPONENT_REGISTRY.map(entry => [entry.id, entry.renderer]));

const baseFields = {
  blockTitle: 'SAMPLE EXPORT', blockHeadline: 'Representative export fixture', blockDesc: 'Generated by scripts/generate-export-fixtures.mjs — see docs/RISE-COMPATIBILITY-MATRIX.md.',
  colorPrimary: '#2563EB', colorAccent: '#F59E0B', colorBg: '#FFFFFF', colorText: '#1F2937',
  borderRadius: '12', shadowDepth: 'soft', borderOutline: true,
  accordionMulti: true, accordionAnimation: true, iconStyle: 'chevron',
  trackCompletion: true, completionMsg: 'Activity complete!'
};

// The 7 components docs/RISE-COMPATIBILITY-MATRIX.md and the manual checklists
// reference by name — chosen to cover the interaction patterns least like each other
// (disclosure, flip/reveal, tabbed panels, quiz+feedback, click-to-annotate, step
// selection, media playback), not an arbitrary sample.
export const EXPORT_FIXTURES = [
  { componentId: 'accordion', filename: 'accordion.html' },
  { componentId: 'flip-cards', filename: 'flip-cards.html' },
  { componentId: 'tab-blocks', filename: 'tabs.html' },
  { componentId: 'multiple-choice', filename: 'multiple-choice.html' },
  { componentId: 'hotspots', filename: 'hotspots.html' },
  { componentId: 'vertical-timeline', filename: 'timeline.html' },
  { componentId: 'audio-player', filename: 'audio-player.html' }
];

export function compileExportFixture(componentId) {
  const entry = getComponentById(COMPONENT_REGISTRY, componentId);
  if (!entry) throw new Error(`No registry entry for "${componentId}"`);
  const config = applyThemeToConfig({ ...baseFields, ...getDefaultConfig(entry) }, theme);
  const appState = {
    selectedComponent: { id: componentId }, activeTheme: theme, componentOverrides: {},
    config, currentProjectId: `fixture-${componentId}`
  };
  return generateIframeContent(appState, componentRegistry, toRgba);
}
